from __future__ import annotations

import logging
import time
from typing import Any, Iterator

import httpx

from app.config import Settings, get_settings

logger = logging.getLogger(__name__)


class FeishuError(Exception):
    def __init__(self, code: int | str, message: str, payload: Any = None) -> None:
        super().__init__(f"[{code}] {message}")
        self.code = code
        self.message = message
        self.payload = payload


class FeishuClient:
    """飞书开放平台：tenant token + 多维表格 + 自定义机器人 webhook。"""

    BASE = "https://open.feishu.cn/open-apis"

    def __init__(self, settings: Settings | None = None, timeout: float = 60.0) -> None:
        self.settings = settings or get_settings()
        if not self.settings.has_feishu:
            raise FeishuError("config", "缺少 FEISHU_APP_ID / FEISHU_APP_SECRET")
        self._http = httpx.Client(timeout=timeout)
        self._token: str | None = None
        self._token_expire_at: float = 0.0

    def close(self) -> None:
        self._http.close()

    def __enter__(self) -> FeishuClient:
        return self

    def __exit__(self, *args: object) -> None:
        self.close()

    def get_tenant_access_token(self, *, force: bool = False) -> str:
        if not force and self._token and self._token_expire_at - 60 > time.time():
            return self._token
        url = f"{self.BASE}/auth/v3/tenant_access_token/internal"
        resp = self._http.post(
            url,
            json={
                "app_id": self.settings.feishu_app_id,
                "app_secret": self.settings.feishu_app_secret,
            },
        )
        resp.raise_for_status()
        data = resp.json()
        if data.get("code") != 0:
            raise FeishuError(data.get("code"), data.get("msg") or "token failed", data)
        self._token = data["tenant_access_token"]
        self._token_expire_at = time.time() + int(data.get("expire") or 7200)
        return self._token

    def _headers(self) -> dict[str, str]:
        return {
            "Authorization": f"Bearer {self.get_tenant_access_token()}",
            "Content-Type": "application/json; charset=utf-8",
        }

    def _api(
        self,
        method: str,
        path: str,
        *,
        params: dict[str, Any] | None = None,
        json_body: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        url = f"{self.BASE}{path}"
        resp = self._http.request(
            method,
            url,
            headers=self._headers(),
            params=params,
            json=json_body,
        )
        try:
            data = resp.json()
        except Exception:
            resp.raise_for_status()
            raise FeishuError(resp.status_code, resp.text[:500])
        # 飞书业务错误常伴随 HTTP 400，优先解析 body
        if data.get("code") not in (0, None) or not resp.is_success:
            if data.get("code") in (0, None) and not resp.is_success:
                raise FeishuError(resp.status_code, resp.text[:500], data)
            if data.get("code") not in (0, None):
                raise FeishuError(
                    data.get("code"),
                    data.get("msg") or "api error",
                    data,
                )
        return data

    # --- bitable meta ---
    def create_bitable_app(self, name: str, *, folder_token: str | None = None) -> dict[str, Any]:
        """创建多维表格应用，返回 app 信息（含 app_token）。"""
        body: dict[str, Any] = {"name": name}
        if folder_token:
            body["folder_token"] = folder_token
        data = self._api("POST", "/bitable/v1/apps", json_body=body)
        return data.get("data") or {}

    def list_tables(self, app_token: str) -> list[dict[str, Any]]:
        data = self._api("GET", f"/bitable/v1/apps/{app_token}/tables")
        items = (data.get("data") or {}).get("items") or []
        return items

    def create_table(
        self,
        app_token: str,
        name: str,
        fields: list[dict[str, Any]],
    ) -> dict[str, Any]:
        """fields 例: [{"field_name":"日期","type":5}, ...]  type 见飞书文档。"""
        body = {"table": {"name": name, "default_view_name": "默认视图", "fields": fields}}
        data = self._api(
            "POST",
            f"/bitable/v1/apps/{app_token}/tables",
            json_body=body,
        )
        return data.get("data") or {}

    def list_fields(self, app_token: str, table_id: str) -> list[dict[str, Any]]:
        data = self._api(
            "GET",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/fields",
        )
        return (data.get("data") or {}).get("items") or []

    def create_field(
        self,
        app_token: str,
        table_id: str,
        field_name: str,
        field_type: int,
        *,
        property_: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        body: dict[str, Any] = {"field_name": field_name, "type": field_type}
        if property_:
            body["property"] = property_
        data = self._api(
            "POST",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/fields",
            json_body=body,
        )
        return data.get("data") or {}

    # --- records ---
    def bitable_list_records(
        self,
        app_token: str,
        table_id: str,
        *,
        page_size: int = 100,
        page_token: str | None = None,
        filter_expr: str | None = None,
    ) -> dict[str, Any]:
        params: dict[str, Any] = {"page_size": page_size}
        if page_token:
            params["page_token"] = page_token
        if filter_expr:
            params["filter"] = filter_expr
        data = self._api(
            "GET",
            f"/bitable/v1/apps/{app_token}/tables/{table_id}/records",
            params=params,
        )
        return data.get("data") or {}

    def iter_records(
        self,
        app_token: str,
        table_id: str,
        *,
        page_size: int = 100,
        filter_expr: str | None = None,
    ) -> Iterator[dict[str, Any]]:
        page_token = None
        while True:
            data = self.bitable_list_records(
                app_token,
                table_id,
                page_size=page_size,
                page_token=page_token,
                filter_expr=filter_expr,
            )
            for item in data.get("items") or []:
                yield item
            if not data.get("has_more"):
                break
            page_token = data.get("page_token")

#!/usr/bin/env python3
"""Create recommended Feishu bitable views on 异常任务 table.

API can create named views; filter UI may still need manual confirm if field_id differs.
Docs: https://open.feishu.cn/document/server-docs/docs/bitable-v1/app-table-view/create
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from app.clients.feishu import FeishuClient, FeishuError
from app.config import get_settings


def list_views(client: FeishuClient, app: str, table: str) -> list[dict]:
    data = client._api(
        "GET", f"/bitable/v1/apps/{app}/tables/{table}/views"
    )
    return (data.get("data") or {}).get("items") or []


def create_view(
    client: FeishuClient, app: str, table: str, name: str, view_type: str = "grid"
) -> dict:
    data = client._api(
        "POST",
        f"/bitable/v1/apps/{app}/tables/{table}/views",
        json_body={"view_name": name, "view_type": view_type},
    )
    return (data.get("data") or {}).get("view") or data.get("data") or {}


def patch_view_filter(
    client: FeishuClient,
    app: str,
    table: str,
    view_id: str,
    field_id: str,
    operator: str,
    value: str,
) -> dict:
    """Best-effort filter patch; Feishu filter value format is version-sensitive."""
    body = {
        "property": {
            "filter_info": {
                "conjunction": "and",
                "conditions": [
                    {
                        "field_id": field_id,
                        "operator": operator,
                        "value": value,
                    }
                ],
            }
        }
    }
    return client._api(
        "PATCH",
        f"/bitable/v1/apps/{app}/tables/{table}/views/{view_id}",
        json_body=body,
    )


def field_id_by_name(client: FeishuClient, app: str, table: str) -> dict[str, str]:
    fields = client.list_fields(app, table)
    return {f.get("field_name"): f.get("field_id") for f in fields if f.get("field_name")}


def main() -> int:
    s = get_settings()
    app = s.feishu_bitable_app_token
    table = s.feishu_table_tasks
    if not app or not table:
        print("ERROR: missing FEISHU_BITABLE_APP_TOKEN / FEISHU_TABLE_TASKS")
        return 2

    wanted = [
        "01_红色任务",
        "02_橙色任务",
        "03_按负责人-梦晴",
        "04_按负责人-潘启豪",
        "05_按负责人-马文静",
        "06_待老板决策",
        "07_全部未关闭",
    ]

    try:
        with FeishuClient(s) as client:
            existing = {v.get("view_name"): v for v in list_views(client, app, table)}
            print("existing views:", list(existing.keys()))
            name_to_id = field_id_by_name(client, app, table)
            print("fields:", name_to_id)

            created = []
            for name in wanted:
                if name in existing:
                    print(f"skip exists: {name} -> {existing[name].get('view_id')}")
                    continue
                v = create_view(client, app, table, name, "grid")
                vid = v.get("view_id")
                print(f"created: {name} -> {vid}")
                created.append((name, vid))

            # try set simple filters where possible
            level_fid = name_to_id.get("等级")
            owner_fid = name_to_id.get("负责人")
            boss_fid = name_to_id.get("需要老板决策")
            status_fid = name_to_id.get("状态")

            def ensure(name: str) -> str | None:
                if name in existing:
                    return existing[name].get("view_id")
                for n, vid in created:
                    if n == name:
                        return vid
                return None

            # Single-select filter value formats vary; try JSON array text
            trials = []
            if level_fid:
                trials.append(
                    ("01_红色任务", level_fid, "is", '["red"]')
                )
                trials.append(
                    ("02_橙色任务", level_fid, "is", '["orange"]')
                )
            if owner_fid:
                for nm, owner in [
                    ("03_按负责人-梦晴", "梦晴"),
                    ("04_按负责人-潘启豪", "潘启豪"),
                    ("05_按负责人-马文静", "马文静"),
                ]:
                    trials.append((nm, owner_fid, "is", f'["{owner}"]'))
            if boss_fid:
                trials.append(("06_待老板决策", boss_fid, "is", "true"))
            if status_fid:
                trials.append(("07_全部未关闭", status_fid, "is", '["open"]'))

            for name, fid, op, val in trials:
                vid = ensure(name)
                if not vid:
                    continue
                try:
                    patch_view_filter(client, app, table, vid, fid, op, val)
                    print(f"filter OK: {name}")
                except FeishuError as e:
                    print(f"filter skip {name}: [{e.code}] {e.message}")

            print()
            print("Base URL:")
            print(f"https://dcnkj1up67d5.feishu.cn/base/{app}?table={table}")
            print("若筛选未生效，请在飞书 UI 打开对应视图点「筛选」按字段配置一次。")
            return 0
    except FeishuError as e:
        print(f"FEISHU ERROR [{e.code}] {e.message}")
        print(e.payload)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

