        "currency": "GBP",
        "title": "demo bulb",
        "asinList": ["B09D9MR3DK"],
        "parentAsinList": ["B0H6X3TWMV"],
        "skuList": ["UK-BM-G4-20W"],
        "mskuList": ["HB-G4-20W-10PK"],
        "brandNameList": ["Levidon"],
        "openDate": "2025-07-01 10:54:21",
        "shopInfos": [
            {"shopName": "特米-UK", "marketplaceName": "英国", "shopId": "397426"}
        ],
        "fieldsMap": {
            "salePrice": {
                "currValue": "520.26",
                "momValue": "370.76",
                "momPercent": "40.3200",
            },
